for(const width of [1280,390])test(`legend hover and focus preserve selection, source and amounts at ${width}px`,async()=>{const h=harness(width);await h.ready;const api=h.ctx.FinanceReadDiagnostics,before=JSON.stringify(api.project()),food=h.node('legend-food'),shopping=h.node('legend-shopping'),first=h.node('segment-food'),second=h.node('segment-shopping');food.onpointerenter({pointerType:'mouse'});assert.equal(first.classList.contains('legend-muted'),false);assert.equal(second.classList.contains('legend-muted'),true);assert.equal(food.classList.contains('legend-highlighted'),true);food.onpointerleave();assert.equal(second.classList.contains('legend-muted'),false);shopping.onfocusin();assert.equal(first.classList.contains('legend-muted'),true);assert.equal(second.classList.contains('legend-muted'),false);shopping.onfocusout({relatedTarget:null});assert.equal(first.classList.contains('legend-muted'),false);assert.equal(JSON.stringify(api.project()),before);assert.ok(h.requests.every(r=>r.method==='GET'));});
